# -----------------------------
# AquaSite animated splash screen
# -----------------------------
splash_html = """<style>
@keyframes aqSplashOut {
  0%, 82% { opacity: 1; visibility: visible; }
  100% { opacity: 0; visibility: hidden; pointer-events: none; }
}
@keyframes aqLogoReveal {
  0% { opacity: 0; filter: brightness(.88) contrast(1.08); }
  14% { opacity: 1; filter: brightness(1.06) contrast(1.10); }
  80% { opacity: 1; filter: brightness(1.03) contrast(1.10); }
  100% { opacity: 0; filter: brightness(1.03) contrast(1.10); }
}
@keyframes aqSweep {
  0% { transform: translateX(-170%) skewX(-14deg); opacity: 0; }
  22% { opacity: 0; }
  36% { opacity: .55; }
  58% { transform: translateX(185%) skewX(-14deg); opacity: 0; }
  100% { transform: translateX(185%) skewX(-14deg); opacity: 0; }
}
@keyframes aqRipple {
  0% { transform: translate(-50%, -50%) scale(.32); opacity: .62; }
  100% { transform: translate(-50%, -50%) scale(2.9); opacity: 0; }
}
@keyframes aqBubble {
  0% { transform: translateY(26px) scale(.72); opacity: 0; }
  18% { opacity: .64; }
  100% { transform: translateY(-175px) scale(1.14); opacity: 0; }
}
@keyframes aqLoader {
  0% { width: 0%; }
  100% { width: 100%; }
}
@keyframes aqGlow {
  0%,100% { opacity: .25; transform: translateX(-50%) scaleX(.80); }
  50% { opacity: .66; transform: translateX(-50%) scaleX(1.08); }
}

.aq-splash {
  position: fixed;
  inset: 0;
  z-index: 999999;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 42%, rgba(20,184,166,.18), transparent 26%),
    radial-gradient(circle at 50% 57%, rgba(14,165,233,.12), transparent 38%),
    linear-gradient(145deg, #031426 0%, #06243d 52%, #083455 100%);
  animation: aqSplashOut 4.15s cubic-bezier(.7,0,.2,1) forwards;
}

.aq-stage {
  position: relative;
  width: min(980px, 90vw);
  text-align: center;
}

.aq-logo-wrap {
  position: relative;
  width: min(790px, 78vw);
  margin: 0 auto;
  animation: aqLogoReveal 3.9s ease forwards;
}

.aq-logo {
  display: block;
  width: 100%;
  height: auto;
  object-fit: contain;
  transform: none !important;
  image-rendering: auto;
  filter: drop-shadow(0 12px 34px rgba(20,184,166,.18));
}

.aq-sweep {
  position: absolute;
  top: 7%;
  bottom: 7%;
  left: 0;
  width: 22%;
  pointer-events: none;
  mix-blend-mode: screen;
  filter: blur(7px);
  background: linear-gradient(
    100deg,
    transparent,
    rgba(255,255,255,.03),
    rgba(218,255,248,.40),
    rgba(255,255,255,.04),
    transparent
  );
  animation: aqSweep 4s ease-in-out forwards;
}

.aq-water-glow {
  position: absolute;
  left: 50%;
  bottom: -1%;
  width: min(430px, 48vw);
  height: 28px;
  transform: translateX(-50%);
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(ellipse, rgba(94,234,212,.72), rgba(56,189,248,.17) 48%, transparent 74%);
  filter: blur(8px);
  animation: aqGlow 2.1s ease-in-out infinite;
}

.aq-ripple {
  position: absolute;
  left: 50%;
  bottom: -2%;
  width: 165px;
  height: 44px;
  border: 1.5px solid rgba(94,234,212,.56);
  border-radius: 50%;
  box-shadow: 0 0 17px rgba(56,189,248,.17);
  pointer-events: none;
  animation: aqRipple 2.25s ease-out infinite;
}
.aq-ripple.r2 { animation-delay: .72s; }
.aq-ripple.r3 { animation-delay: 1.44s; }

.aq-bubble {
  position: absolute;
  bottom: 5%;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: 1px solid rgba(186,230,253,.72);
  background: radial-gradient(circle at 35% 30%, rgba(255,255,255,.9), rgba(125,211,252,.16) 38%, transparent 72%);
  box-shadow: 0 0 11px rgba(56,189,248,.22);
  pointer-events: none;
  animation: aqBubble 2.9s ease-in infinite;
}
.aq-bubble.b1 { left: 28%; animation-delay: .18s; width: 7px; height: 7px; }
.aq-bubble.b2 { left: 39%; animation-delay: .92s; width: 11px; height: 11px; }
.aq-bubble.b3 { left: 61%; animation-delay: .46s; width: 7px; height: 7px; }
.aq-bubble.b4 { left: 72%; animation-delay: 1.28s; width: 10px; height: 10px; }

.aq-loader-zone {
  width: min(360px, 56vw);
  margin: 22px auto 0 auto;
  text-align: center;
}

.aq-loader-track {
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(125,211,252,.13);
  border: 1px solid rgba(125,211,252,.22);
}

.aq-loader-fill {
  width: 0%;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #5eead4, #7dd3fc, #e0f2fe);
  box-shadow: 0 0 16px rgba(94,234,212,.50);
  animation: aqLoader 3.25s cubic-bezier(.18,.75,.23,1) forwards;
}

.aq-loader-copy {
  margin-top: 10px;
  color: #dbeafe;
  text-transform: uppercase;
  letter-spacing: .18em;
  font-size: .68rem;
  font-weight: 800;
  opacity: .82;
}

@media (max-width: 700px) {
  .aq-stage { width: 95vw; }
  .aq-logo-wrap { width: 92vw; }
  .aq-loader-zone { width: 68vw; }
}

@media (prefers-reduced-motion: reduce) {
  .aq-splash { animation-duration: 1.1s; }
  .aq-logo-wrap, .aq-sweep, .aq-water-glow, .aq-ripple, .aq-bubble, .aq-loader-fill {
    animation: none !important;
  }
  .aq-loader-fill { width: 100%; }
}
</style>
<div class="aq-splash" aria-hidden="true">
  <div class="aq-stage">
    <div class="aq-logo-wrap">
      <img class="aq-logo" src="data:image/png;base64," alt="AquaSite">
      <div class="aq-sweep"></div>
      <div class="aq-water-glow"></div>
      <div class="aq-ripple"></div>
      <div class="aq-ripple r2"></div>
      <div class="aq-ripple r3"></div>
      <div class="aq-bubble b1"></div>
      <div class="aq-bubble b2"></div>
      <div class="aq-bubble b3"></div>
      <div class="aq-bubble b4"></div>
    </div>
    <div class="aq-loader-zone">
      <div class="aq-loader-track"><div class="aq-loader-fill"></div></div>
      <div class="aq-loader-copy">Loading AquaSite</div>
    </div>
  </div>
</div>"""

st.markdown(splash_html, unsafe_allow_html=True)

